import pandas as pd


def _is_null(x):
    return x is None or (isinstance(x, float) and pd.isna(x)) or pd.isna(x)


def _null_aware_eq(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    # Case-insensitive / flexible lookup for input relation names.
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    # also try without underscores differences
    for k, v in inputs.items():
        if k.lower().replace("_", "") == lname.replace("_", ""):
            return v
    raise KeyError(f"Could not find input relation matching '{name}' among {list(inputs.keys())}")


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, "DIM_CUSTOMER").copy()
    stg = _get_input(inputs, "STG_CUSTOMER").copy()

    # Ensure expected columns exist
    dim_cols = ["customer_id", "name", "segment", "eff_start_date", "eff_end_date", "is_current"]
    for c in dim_cols:
        if c not in dim.columns:
            dim[c] = pd.NA
    dim = dim[dim_cols]

    stg_cols = ["customer_id", "name", "segment", "update_date"]
    for c in stg_cols:
        if c not in stg.columns:
            stg[c] = pd.NA
    stg = stg[stg_cols]

    # Step 1: Deduplicate STG_CUSTOMER -> latest per customer_id by update_date,
    # tie-break on greater (name, segment) lexicographically.
    if len(stg) > 0:
        stg_sorted = stg.sort_values(
            by=["customer_id", "update_date", "name", "segment"],
            ascending=[True, False, False, False],
            kind="mergesort",
        )
        stg_dedup = stg_sorted.drop_duplicates(subset=["customer_id"], keep="first").reset_index(drop=True)
    else:
        stg_dedup = stg.copy()

    # Work on dim as list of dict rows for mutability/append
    dim_records = dim.to_dict("records")

    # Build index of current row position per customer_id (assuming at most one current row)
    current_pos = {}
    for idx, rec in enumerate(dim_records):
        if rec.get("is_current") == 1:
            cid = rec.get("customer_id")
            current_pos[cid] = idx

    new_rows = []

    for _, s in stg_dedup.iterrows():
        cid = s["customer_id"]
        s_name = s["name"]
        s_segment = s["segment"]
        s_update_date = s["update_date"]

        if cid not in current_pos:
            # No current row exists -> simple insert
            new_rows.append({
                "customer_id": cid,
                "name": s_name,
                "segment": s_segment,
                "eff_start_date": s_update_date,
                "eff_end_date": pd.NA,
                "is_current": 1,
            })
        else:
            pos = current_pos[cid]
            c = dim_records[pos]
            name_eq = _null_aware_eq(c.get("name"), s_name)
            seg_eq = _null_aware_eq(c.get("segment"), s_segment)

            if (not name_eq) or (not seg_eq):
                # Expire current row
                dim_records[pos]["eff_end_date"] = s_update_date
                dim_records[pos]["is_current"] = 0

                # Insert new version
                new_rows.append({
                    "customer_id": cid,
                    "name": s_name,
                    "segment": s_segment,
                    "eff_start_date": s_update_date,
                    "eff_end_date": pd.NA,
                    "is_current": 1,
                })
            else:
                # No change -> do nothing
                pass

    result_records = dim_records + new_rows
    result_df = pd.DataFrame(result_records, columns=dim_cols)

    return {"dim_customer_out": result_df}
